window.SB_DATA = {"decks":[{"id":"math-algebra-basics","title":"Math: Algebra Basics","topic":"Math","cards":[["What is a variable?","A symbol (like x) representing an unknown value — a mystery box to be solved for."],["Expression vs equation?","Expression = phrase (3x + 2), no equals sign. Equation = sentence (3x + 2 = 11), has an equals sign."],["What are like terms?","Terms with the exact same variable part, like 7x and −2x. Only like terms can combine."],["What is a coefficient?","The number multiplying the variable — 5 in '5y'."],["Golden rule of equations?","Whatever you do to one side, do to the other. A balanced scale stays balanced."],["Simplify: 4x − 7 + 2x − 3","6x − 10 (combine x-terms, then numbers, keeping signs attached)."],["First step to solve 3x + 5 = 20?","Subtract 5 from both sides → 3x = 15."],["What does the distributive property say?","a(b + c) = ab + ac — multiply each term inside the parentheses."],["How do you check a solution?","Substitute it back into the original equation — both sides must match."],["Solve: −x = 5","x = −5 (divide both sides by −1)."]]},{"id":"math-fractions-decimals-percents","title":"Math: Fractions, Decimals & Percents","topic":"Math","cards":[["1/2 as decimal and percent","0.5 = 50%"],["1/4 as decimal and percent","0.25 = 25%"],["1/3 as decimal and percent","0.333… ≈ 33.3%"],["1/5 as decimal and percent","0.2 = 20%"],["1/8 as decimal and percent","0.125 = 12.5%"],["Fraction → decimal method","Divide numerator by denominator (top ÷ bottom)."],["Decimal → percent method","Move decimal point 2 places right (0.07 → 7%)."],["Rule for adding fractions","Common denominator first, then add numerators only."],["Keep, change, flip","Fraction division: keep first, change ÷ to ×, flip the second fraction."],["What does percent mean?","'Per hundred' — 25% = 25 out of every 100 = 0.25."]]},{"id":"math-geometry-fundamentals","title":"Math: Geometry Fundamentals","topic":"Math","cards":[["Triangle angle sum","Exactly 180°, always, every triangle."],["Pythagorean theorem","a² + b² = c² — right triangles only; c is the hypotenuse."],["What's the hypotenuse?","The longest side, across from the 90° angle."],["Vertical angles","Opposite angles at a crossing — always congruent."],["Angles on a straight line","Sum to 180° (supplementary)."],["Triangle area formula","A = ½ × base × height."],["Circle area and circumference","A = πr² · C = 2πr (or πd)."],["Equilateral triangle angles","All 60° — equal sides mean equal angles."],["Volume of a prism or cylinder","Base area × height."],["Common Pythagorean triples","3-4-5, 5-12-13, 8-15-17 (and their multiples)."]]},{"id":"math-trigonometry-essentials","title":"Math: Trigonometry Essentials","topic":"Math","cards":[["SOH","Sine = Opposite / Hypotenuse"],["CAH","Cosine = Adjacent / Hypotenuse"],["TOA","Tangent = Opposite / Adjacent"],["How to find a missing side","Pick the ratio with the known angle + side and the wanted side; substitute; solve with algebra."],["How to find a missing angle","Use two sides to compute a ratio, then apply inverse trig (sin⁻¹, cos⁻¹, tan⁻¹)."],["Which side is 'opposite'?","Across from the angle in question — it changes if you switch angles."],["45-45-90 side ratio","1 : 1 : √2 (legs equal, hypotenuse = leg × √2)."],["30-60-90 side ratio","1 : √3 : 2 (short leg, long leg, hypotenuse)."],["sin 30°","1/2 (or 0.5)"],["Largest a sine or cosine value can be","1 — opposite can never exceed the hypotenuse."]]},{"id":"math-linear-equations-graphing","title":"Math: Linear Equations & Graphing","topic":"Math","cards":[["In y = mx + b, what is m?","The slope — rise over run, how much y changes per unit x."],["In y = mx + b, what is b?","The y-intercept — where the line crosses the y-axis."],["Slope formula from two points","m = (y₂ − y₁) / (x₂ − x₁)"],["How to graph y = mx + b fast","Plot b on the y-axis, then step by m (rise/run) to a second point; draw the line."],["Slopes of parallel lines","Identical slopes, different intercepts."],["Slopes of perpendicular lines","Negative reciprocals — they multiply to −1 (e.g., 3 and −1/3)."],["Substitution method","Solve one equation for one variable, substitute that expression into the other equation."],["Elimination method","Add or subtract the equations to eliminate one variable, then solve."],["When a system has no solution","The lines are parallel — same slope, never intersect."],["Real-world meaning of slope","A rate of change: dollars per hour, km per liter, points per game."]]},{"id":"math-word-problems-strategies","title":"Math: Word Problem Strategies","topic":"Math","cards":[["'More than / increased by' means","Addition (+)."],["'Less than' means","Subtraction — and it reverses the order: '5 less than x' = x − 5."],["'Of' means (in word problems)","Multiply — 'half of 30' = ½ × 30 = 15."],["'Per' means","Divide — a rate: miles per hour = miles ÷ hours."],["'Is / was / totals' means","Equals (=) — the backbone of your equation."],["Step 1 of the word problem routine","Read the entire problem once without writing anything."],["Why define variables in English?","'x = minutes per day' prevents setting up the wrong equation — precision before algebra."],["The three sanity checks","Answer the asked question · substitute back · compare to an estimate."],["'Consecutive integers' in algebra","x, x+1, x+2 (consecutive even/odd: x, x+2, x+4)."],["Best first move when stuck","Draw a picture, table, or timeline — visualizing reveals the relationships."]]},{"id":"biology-cell-basics","title":"Biology: Cell Basics","topic":"Biology","cards":[["What is a cell?","The smallest unit of life."],["What is an organelle?","A specialized structure inside a cell with a specific job."],["Job of the nucleus?","Stores DNA and controls the cell's activities."],["Job of mitochondria?","Make ATP energy from food — the cell's power plant."],["Job of ribosomes?","Build proteins."],["Job of the cell membrane?","Controls what enters and leaves the cell."],["Where is DNA in a prokaryote?","Free in the cytoplasm — there is no nucleus."],["Two structures plant cells have that animal cells don't","Chloroplasts and a cell wall."],["Prokaryote vs eukaryote in one line","Prokaryote = no nucleus; eukaryote = nucleus plus organelles."],["Job of the vacuole?","Stores water, food and waste (huge in plant cells)."]]},{"id":"biology-photosynthesis","title":"Biology: Photosynthesis","topic":"Biology","cards":[["Photosynthesis equation","6CO2 + 6H2O + light → C6H12O6 + 6O2"],["Inputs of photosynthesis","Carbon dioxide, water and sunlight."],["Outputs of photosynthesis","Glucose and oxygen."],["Where photosynthesis happens","In chloroplasts (specifically thylakoids + stroma)."],["Job of chlorophyll","Absorb light energy — it's the green pigment."],["Thylakoid vs stroma","Thylakoids = light-dependent reactions; stroma = Calvin cycle."],["What stage 1 produces","ATP, NADPH and oxygen (from splitting water)."],["What the Calvin cycle produces","Glucose, using CO2 plus ATP and NADPH."],["Where the released oxygen comes from","Splitting water molecules — not CO2."],["Light-independent means","Doesn't use light directly — but needs stage 1's ATP and NADPH, so it stalls in prolonged dark."]]},{"id":"biology-dna-and-genetics","title":"Biology: DNA & Genetics","topic":"Biology","cards":[["DNA base pairing rule","A pairs with T; G pairs with C."],["Shape of DNA","A double helix — two twisted strands with base pairs as rungs."],["What is a gene?","A stretch of DNA with instructions for one protein."],["What is an allele?","One version of a gene — you get two per gene, one from each parent."],["Genotype vs phenotype","Genotype = alleles you carry (Tt); phenotype = the trait you show (tall)."],["Homozygous vs heterozygous","Homozygous = matching alleles (TT or tt); heterozygous = one of each (Tt)."],["When does a recessive trait appear?","Only when both alleles are recessive (tt)."],["Tt x Tt phenotype ratio","3:1 — 75% dominant, 25% recessive."],["What does a Punnett square show?","All possible offspring genotypes and their probabilities — not guarantees."],["What is a carrier?","A heterozygote who carries a recessive allele but doesn't show the trait."]]},{"id":"biology-human-body-systems","title":"Biology: Human Body Systems","topic":"Biology","cards":[["Levels of body organization","Cell → tissue → organ → organ system → organism."],["What is homeostasis?","Keeping internal conditions stable — temperature, blood sugar, water balance."],["Circulatory system's job","Pump blood to deliver oxygen and nutrients and remove wastes."],["Respiratory system's job","Bring in oxygen, expel carbon dioxide."],["Digestive system's job","Break food into molecules cells can absorb."],["Nervous vs endocrine","Nervous = fast electrical signals; endocrine = slower hormone signals."],["Excretory system's job","Filter blood and balance water and salts (kidneys lead)."],["Skeletal system does two jobs","Support/structure and making new blood cells."],["Integumentary system","Skin, hair and nails — the body's barrier and temperature regulator."],["Which system makes hormones?","The endocrine system (glands like the thyroid and adrenal)."]]},{"id":"biology-ecosystems","title":"Biology: Ecosystems","topic":"Biology","cards":[["What is an ecosystem?","All living things in an area plus the nonliving parts (sunlight, water, soil) they interact with."],["Producer vs consumer","Producers make their own food; consumers must eat other organisms."],["What do decomposers do?","Break down dead material and recycle nutrients back to producers."],["Food chain vs food web","A chain is one path; a web is all the connected chains in an ecosystem."],["Which way do food chain arrows point?","Toward the eater — the direction energy flows."],["What is a trophic level?","A feeding position: producer, primary consumer, secondary consumer, and so on."],["The 10 percent rule","Only ~10% of energy passes to the next trophic level; the rest is lost as heat and waste."],["Why are top predators rare?","Energy shrinks 10x per level, so little energy is left at the top to support many predators."],["What two factors determine a biome?","Temperature and rainfall."],["Example biome pairs","Hot + wet = rainforest; hot + dry = desert; cold + dry = tundra."]]},{"id":"biology-mitosis-vs-meiosis","title":"Biology: Mitosis vs Meiosis","topic":"Biology","cards":[["What does PMAT stand for?","Prophase, Metaphase, Anaphase, Telophase — the four phases of mitosis."],["Purpose of mitosis","Growth and repair: making identical new body cells."],["Purpose of meiosis","Making gametes (sperm and eggs) for sexual reproduction."],["Mitosis vs meiosis: number of cells","Mitosis makes 2 identical cells; meiosis makes 4 unique cells."],["What is crossing over?","Chromosome pairs swapping DNA segments in prophase I of meiosis — a big source of variation."],["Diploid vs haploid (humans)","Diploid = 46 chromosomes (body cells); haploid = 23 (gametes)."],["Where does meiosis occur in animals?","Ovaries and testes — wherever gametes are made."],["What is cytokinesis?","The final split of the cytoplasm that separates the new cells."],["Fertilization chromosome math","Haploid (23) + haploid (23) = diploid (46) in the zygote."],["Which process creates genetic variation?","Meiosis — through crossing over and the random separation of chromosome pairs."]]},{"id":"chemistry-atomic-structure","title":"Chemistry: Atomic Structure","topic":"Chemistry","cards":[["Charge and location of a proton","Positive, inside the nucleus."],["Charge and location of a neutron","Neutral (no charge), inside the nucleus."],["Charge and location of an electron","Negative, outside the nucleus."],["Atomic number tells you","The number of protons — and therefore the element."],["Mass number formula","Protons + neutrons."],["How to find neutrons","Mass number − atomic number."],["What is an isotope?","Same element, same protons, different neutrons — like carbon-12 vs carbon-14."],["Where is almost all the atom's mass?","In the nucleus (protons and neutrons)."],["What is an ion?","An atom that gained or lost electrons, giving it a net charge."],["Rutherford's gold foil experiment proved","Atoms are mostly empty space with a tiny dense positive nucleus."]]},{"id":"chemistry-periodic-table","title":"Chemistry: Periodic Table","topic":"Chemistry","cards":[["Group vs period","Group = vertical column (same valence electrons); period = horizontal row (same shells)."],["What are valence electrons?","Outer-shell electrons — they determine how an atom bonds."],["Group 1 is called","The alkali metals — highly reactive, 1 valence electron."],["Group 17 is called","The halogens — reactive nonmetals that need 1 more electron."],["Group 18 is called","The noble gases — full shells, nearly unreactive."],["Where are the metals?","Left and center — about three-quarters of the table."],["Atomic radius trend","Decreases across a period, increases down a group."],["Electronegativity trend","Increases up and to the right — fluorine is the strongest."],["Which element is the most electronegative?","Fluorine."],["Why do noble gases barely react?","Their outer shells are already full — no drive to gain, lose or share."]]},{"id":"chemistry-chemical-bonding","title":"Chemistry: Chemical Bonding","topic":"Chemistry","cards":[["Why do atoms bond?","To reach a full outer electron shell — the octet rule."],["Ionic bond in one line","A metal transfers electrons to a nonmetal; opposite charges attract."],["Covalent bond in one line","Two atoms (usually nonmetals) share electron pairs."],["Metallic bond in one line","Metal atoms pool their valence electrons into a mobile sea."],["Cation vs anion","Cation = positive (lost electrons); anion = negative (gained electrons)."],["Signature of an ionic compound","A metal bonded to a nonmetal, e.g., NaCl."],["Properties of ionic compounds","Hard crystals, high melting points, conduct when dissolved in water."],["Properties of covalent compounds","Molecules with lower melting/boiling points; don't conduct."],["What is a polar covalent bond?","Unequal sharing — the more electronegative atom pulls harder, like oxygen in water."],["Why do metals bend instead of shatter?","The electron sea lets atoms slide past each other without breaking the bonding."]]},{"id":"chemistry-chemical-reactions","title":"Chemistry: Chemical Reactions","topic":"Chemistry","cards":[["What does the arrow in an equation mean?","Yields — reactants become products."],["Law of conservation of mass","Atoms are neither created nor destroyed; equations must reflect it."],["What is a coefficient?","The number in front of a formula — the number you change when balancing."],["What is a subscript?","The small number inside a formula — never change it when balancing."],["Synthesis reaction","A + B → AB (two things join into one)."],["Decomposition reaction","AB → A + B (one compound breaks apart)."],["Single replacement","A + BC → AC + B (one element kicks out another)."],["Double replacement","AB + CD → AD + CB (two compounds swap partners)."],["Combustion reaction","Fuel + O2 → CO2 + H2O (burning in oxygen)."],["What does (aq) mean?","Aqueous — dissolved in water."]]},{"id":"chemistry-moles-and-stoichiometry","title":"Chemistry: Moles & Stoichiometry","topic":"Chemistry","cards":[["What is a mole?","A counting unit: 6.022 × 10²³ particles — like a dozen, but for atoms."],["Avogadro's number","6.022 × 10²³ particles per mole."],["What is molar mass?","The mass of one mole in grams — read from the periodic table."],["Molar mass of H2O","18.02 g/mol (2 × 1.008 + 16.00)."],["Grams → moles","Divide grams by molar mass."],["Moles → grams","Multiply moles by molar mass."],["Moles → particles","Multiply by Avogadro's number."],["What is a mole ratio?","The coefficient ratio between two substances in a balanced equation."],["The stoichiometry staircase","grams A → moles A → moles B → grams B."],["What is a limiting reactant?","The reactant that runs out first; it caps how much product can form."]]},{"id":"chemistry-acids-and-bases","title":"Chemistry: Acids & Bases","topic":"Chemistry","cards":[["What is an acid?","A substance that releases H+ ions in water; tastes sour, turns blue litmus red."],["What is a base?","A substance that accepts H+ (often releasing OH−); feels slippery, turns red litmus blue."],["What is pH?","A 0-14 scale of acidity: below 7 acid, 7 neutral, above 7 base."],["What does one pH unit mean?","A 10× change in acidity — pH 4 is ten times more acidic than pH 5."],["pH of pure water","7 — neutral."],["pH of blood","About 7.4 — slightly basic, and tightly maintained."],["Neutralization equation","Acid + base → salt + water."],["What is an indicator?","A substance that changes color in acids vs bases — litmus is the classic."],["What is a salt?","The ionic compound left after neutralization — table salt, NaCl, is the famous example."],["Why do antacids work?","They're mild bases that neutralize excess stomach acid, raising pH toward comfort."]]},{"id":"physics-motion-and-forces","title":"Physics: Motion and Forces","topic":"Physics","cards":[["Speed formula","v = d/t — distance divided by time (m/s)."],["Speed vs velocity","Velocity is speed plus a direction; 25 m/s east is a velocity."],["Acceleration formula","a = (final velocity − starting velocity) ÷ time."],["Units of acceleration","m/s² — meters per second, per second."],["Newton's 1st law","An object at rest stays at rest and an object in motion keeps moving unless a net force acts (inertia)."],["Newton's 2nd law","F = ma — force equals mass times acceleration."],["Newton's 3rd law","Every action force has an equal and opposite reaction force."],["Unit of force","The newton (N) = 1 kg · m/s²."],["Weight formula","W = mg, with g ≈ 9.8 m/s² on Earth."],["Mass vs weight","Mass is the amount of matter (kg); weight is gravity's force on it (N) and changes with location."]]},{"id":"physics-energy-work-power","title":"Physics: Energy, Work and Power","topic":"Physics","cards":[["Kinetic energy formula","KE = ½mv² — half of mass times speed squared."],["Potential energy formula (gravity)","PE = mgh — mass times g times height."],["Unit of energy","The joule (J)."],["Law of conservation of energy","Energy is never created or destroyed — only transformed."],["Roller coaster energy story","First hill = maximum PE; PE trades to KE on the way down; friction leaks some to heat and sound."],["Work formula","W = Fd — force times distance moved in the force's direction."],["Power formula","P = W/t — work divided by time."],["Unit of power","The watt (W); 1 watt = 1 joule per second."],["Why highway crashes are worse","KE squares the speed — double speed means four times the energy."],["What friction does to energy","Converts mechanical energy into heat — energy isn't lost, just spread out."]]},{"id":"physics-waves-and-sound","title":"Physics: Waves and Sound","topic":"Physics","cards":[["Wave speed equation","v = f × λ (speed = frequency × wavelength)."],["Crest and trough","Crest = highest point; trough = lowest point of a wave."],["Wavelength symbol and meaning","λ — the distance between matching points, like crest to crest."],["Amplitude means","Height from the rest position — bigger amplitude, more energy, louder sound."],["Frequency means","Waves per second, in hertz (Hz)."],["Frequency's effect on pitch","Higher frequency = higher pitch; lower frequency = lower pitch."],["Period formula","T = 1/f — seconds per wave."],["Speed of sound in air","About 343 m/s at room temperature."],["Doppler effect in one line","Moving toward = bunched waves = higher pitch; moving away = stretched = lower pitch."],["Why space is silent","Sound is a vibration of a medium — with no air, there's nothing to vibrate."]]},{"id":"physics-electricity-basics","title":"Physics: Electricity Basics","topic":"Physics","cards":[["Ohm's law","V = IR — voltage (V) = current (A) × resistance (Ω)."],["Current is measured in","Amperes (A) — the flow rate of charge."],["Voltage is measured in","Volts (V) — the electrical push."],["Resistance is measured in","Ohms (symbol Ω)."],["What carries current in wires?","Moving electrons (negative charge)."],["Water analogy: voltage","Pump pressure — how hard the water is pushed."],["Water analogy: current","Flow rate — how much water passes per second."],["Series circuit rule","One path, same current everywhere; resistances add; one break kills all."],["Parallel circuit rule","Branches each get full voltage; one break leaves others working; total resistance drops."],["How to find current from V and R","I = V ÷ R (Ohm's law rearranged)."]]},{"id":"physics-magnetism","title":"Physics: Magnetism","topic":"Physics","cards":[["Rule of poles","Opposites attract; likes repel."],["Can a magnet have a single pole?","No — break a magnet and you get two complete smaller magnets."],["What do field lines show?","The direction and strength of a magnetic field; closer lines = stronger field."],["Three ferromagnetic elements","Iron, nickel, cobalt."],["What is an electromagnet?","A coil of wire with current flowing through it (plus an iron core) — a switchable magnet."],["Three ways to strengthen an electromagnet","More turns of wire, more current, a better (iron) core."],["Oersted's discovery","An electric current deflects a compass needle — electricity creates magnetism."],["Motor effect","A current-carrying wire in a magnetic field gets pushed sideways."],["Job of the commutator","Reverses the current every half-turn so the motor keeps spinning in one direction."],["Why Earth acts like a magnet","Its molten iron outer core churns, generating a planet-scale magnetic field."]]},{"id":"physics-light-and-optics","title":"Physics: Light and Optics","topic":"Physics","cards":[["Law of reflection","Angle of incidence = angle of reflection, measured from the normal."],["What is the normal?","The perpendicular line to the surface at the point where light hits."],["Refraction is","The bending of light when it changes speed crossing into a new medium."],["Bending rule for refraction","Into a slower medium → toward the normal; into a faster one → away."],["Why a straw looks bent in water","Refraction: light from the underwater part changes speed at the surface and bends."],["Convex lens does what","Converges (focuses) light to a focal point — magnifying glass, eye, camera."],["Concave lens does what","Diverges (spreads) light — used in glasses for nearsightedness."],["Why prisms make rainbows","Dispersion: each color bends a different amount — violet most, red least."],["Why an apple looks red","It reflects red light to your eye and absorbs the other colors."],["Why the sky is blue","Air molecules scatter short-wavelength blue light across the sky."]]},{"id":"history-ancient-civilizations","title":"History: Ancient Civilizations","topic":"History","cards":[["First writing system, and where","Cuneiform, in Mesopotamia (Sumer), around 3200 BCE."],["Why civilizations started in river valleys","Rivers provided water, fertile soil and transport → food surpluses → cities, jobs, government, writing."],["Hammurabi's Code","An early written law code from Babylon — laws published so everyone knew the punishments."],["Egypt's god-king was called a","Pharaoh."],["Egyptian writing system","Hieroglyphics — picture symbols, decoded with the Rosetta Stone."],["Athens vs Sparta in three words","Athens: ideas, trade, democracy. Sparta: war, discipline, obedience."],["A Greek city-state is called a","Polis."],["Philosophy chain in order","Socrates → Plato → Aristotle."],["Rome's government before the emperors","A republic — elected leaders and the Senate, no king (from 509 BCE)."],["Traditional end of the western Roman Empire","476 CE, when the last western emperor was deposed."]]},{"id":"history-american-revolution","title":"History: American Revolution","topic":"History","cards":[["The war begins here, April 1775","Lexington and Concord — 'the shot heard round the world.'"],["Declaration of Independence date","July 4, 1776."],["Main author of the Declaration","Thomas Jefferson."],["Turning point battle, 1777","Saratoga — the victory that won France as an ally."],["Why France mattered","French navy, money and troops trapped Cornwallis and forced the surrender at Yorktown."],["Final major battle, 1781","Yorktown — Cornwallis surrenders to Washington."],["Treaty that ended the war, 1783","Treaty of Paris: independence recognized, borders to the Mississippi."],["Boston Tea Party, 1773","Colonists dumped 342 chests of British tea into the harbor to protest the tea tax."],["Patriots vs Loyalists","Patriots wanted independence; Loyalists stayed loyal to the Crown."],["The weak first US government","The Articles of Confederation — replaced by the Constitution in 1787."]]},{"id":"history-world-war-i","title":"History: World War I","topic":"History","cards":[["MAIN stands for","Militarism, Alliances, Imperialism, Nationalism — the four long-term causes of WWI."],["Spark of WWI","Assassination of Archduke Franz Ferdinand, June 1914, Sarajevo."],["WWI dates","1914–1918."],["No man's land is","The deadly strip of ground between enemy trenches."],["Why the US entered in 1917","German U-boat attacks (including the Lusitania) and the Zimmermann Telegram."],["Armistice date","November 11, 1918 — the 11th hour of the 11th day of the 11th month."],["War guilt clause","The Versailles clause forcing Germany to accept full blame for the war."],["Reparations","Huge payments Germany owed the Allies under Versailles — wrecking its economy."],["League of Nations","The post-WWI peace organization — weakened because the US never joined."],["How Versailles fed WWII","Humiliation, lost land, economic collapse and resentment gave extremists like Hitler their opening."]]},{"id":"history-world-war-ii","title":"History: World War II","topic":"History","cards":[["WWII dates","1939–1945."],["The war begins when","Germany invades Poland, September 1, 1939; Britain and France declare war."],["Appeasement means","Giving in to an aggressor's demands to avoid war — e.g., Munich, 1938."],["Pearl Harbor","December 7, 1941 — Japan's surprise attack that brought the US into the war."],["Eastern Front turning point","Stalingrad, 1942–43 — Germany's advance dies and an entire army surrenders."],["Pacific turning point","Midway, June 1942 — Japan loses its carrier superiority."],["D-Day","June 6, 1944 — the Allied landings at Normandy, opening the western front."],["V-E Day","May 8, 1945 — Germany surrenders."],["V-J Day","September 2, 1945 — Japan surrenders after atomic bombs on Hiroshima and Nagasaki."],["The postwar peace organization","The United Nations, founded 1945."]]},{"id":"history-cold-war","title":"History: Cold War","topic":"History","cards":[["Cold War dates","About 1947–1991."],["Why 'cold' war","The superpowers never fought each other directly — nuclear weapons made direct war unthinkable."],["Containment means","US policy to stop communism spreading anywhere — by aid, alliances and proxy wars."],["Truman Doctrine, 1947","US pledge to aid nations resisting communist takeover."],["Marshall Plan","US money rebuilding Western Europe so communism couldn't take root in poverty."],["Berlin Airlift, 1948–49","Western allies flew supplies into blockaded West Berlin until the USSR backed down."],["Why the Berlin Wall was built, 1961","To stop East Germans from fleeing to the West."],["Cuban Missile Crisis, 1962","A 13-day standoff over Soviet missiles in Cuba — the closest the world came to nuclear war."],["Berlin Wall falls","November 9, 1989."],["USSR dissolves","December 1991 — the Soviet Union splits into 15 independent countries."]]},{"id":"history-civil-rights-movement","title":"History: Civil Rights Movement","topic":"History","cards":[["Brown v. Board, 1954","Supreme Court ruling that school segregation is unconstitutional."],["Rosa Parks, December 1955","Arrested for refusing to give up her bus seat — sparked the Montgomery Bus Boycott."],["Montgomery Bus Boycott length","381 days; it ended with desegregated buses."],["MLK's famous speech, August 1963","'I Have a Dream,' at the March on Washington."],["Civil Rights Act of 1964","Banned segregation in public places and employment discrimination."],["Voting Rights Act of 1965","Banned literacy tests and poll taxes; protected Black voting rights."],["Bloody Sunday, 1965","Selma marchers beaten on the Edmund Pettus Bridge — pushed voting rights forward."],["MLK's death","Assassinated April 4, 1968, in Memphis, Tennessee."],["Jim Crow laws","State laws enforcing racial segregation under 'separate but equal.'"],["The movement's core strategy","Nonviolent direct action — boycotts, sit-ins, marches."]]},{"id":"sat-sat-reading-strategies","title":"SAT Prep: SAT Reading Strategies","topic":"SAT Prep","cards":[["Digital SAT Reading & Writing format","54 questions, 64 minutes, two 32-minute adaptive modules of 27 questions."],["Seconds per reading question","About 71. Check pace every 8-10 questions."],["First move on any reading question","Read the question stem before the passage so you know your job."],["What justifies a correct answer?","Specific words in the passage — if you can't point to them, don't pick it."],["Three wrong-answer patterns","Too extreme, half-true, true-but-irrelevant."],["Inference rule","Stay one small step from the text — never a leap, never outside knowledge."],["Function questions ask...","Why the author included a line — check the context around it."],["Two-pass strategy","Easy questions in order first; flag resistors and return with banked time."],["Blank answers on the SAT","Never — there is no penalty for guessing, so always answer."],["Best pacing drill","Timed practice with a visible per-question timer, weaned down to periodic clock checks."]]},{"id":"sat-sat-writing-grammar","title":"SAT Prep: SAT Writing & Grammar","topic":"SAT Prep","cards":[["What is a comma splice?","Two complete sentences joined by only a comma — always wrong on the SAT."],["Four legal fixes for a comma splice","Semicolon · colon · period · comma + coordinating conjunction (and, but, so)."],["Colon rule","Complete sentence before the colon; list, definition or explanation after."],["When is a semicolon correct?","Between two closely related complete sentences, or to separate list items that contain commas."],["Its vs it's","Expand to 'it is' — if it fits, use the apostrophe; otherwise possessive 'its.'"],["Singular culprits in agreement","Each, every, either, neither, everyone — all take singular verbs."],["What is a dangling modifier?","An opening descriptive phrase whose doer never appears; fix by naming the actor after the comma."],["Transition question method","Decide the logic (contrast/cause/addition/example) BEFORE reading the answer choices."],["Concision rule","Pick the shortest answer that is grammatical and preserves the meaning."],["Example of redundancy","'Return back,' 'annual yearly,' 'end result' — saying it twice never helps."]]},{"id":"sat-sat-math-strategies","title":"SAT Prep: SAT Math Strategies","topic":"SAT Prep","cards":[["Digital SAT math format","44 questions, 70 minutes, two adaptive modules, calculator allowed throughout."],["Four content areas and weights","Algebra ~35%, Advanced Math ~35%, Data Analysis ~15%, Geometry & Trig ~15%."],["Desmos move for systems","Graph both equations; click the intersection point."],["Desmos move for hard equations","Graph y = (equation) and read the x-intercepts as solutions."],["Fill-in answer entry","Decimal or fraction, equivalent forms accepted (0.5 = 1/2)."],["Fill-in rounding rule","Follow 'nearest tenth/hundredth' instructions exactly or the answer is wrong."],["Seconds per math question","About 95 — sweep easy ones first, flag the sticky ones."],["Why first-module accuracy matters","Careless misses route you to an easier second module with a lower score ceiling."],["Top process errors to check","Wrong quantity solved for · unit mismatch · dropped negative · percent form."],["What is an error log?","One line per practice miss — what happened plus the fix — reviewed weekly for patterns."]]},{"id":"sat-sat-vocabulary","title":"SAT Prep: SAT Vocabulary","topic":"SAT Prep","cards":[["Corroborate","To confirm or support with evidence (synonyms: substantiate, verify)."],["Undermine","To weaken or damage gradually (synonyms: weaken, subvert; antonym: bolster)."],["Ambivalent","Having mixed or conflicting feelings about something."],["Pragmatic","Practical, focused on what actually works (antonym: idealistic)."],["Candid","Honest and direct (synonyms: frank, forthright; antonym: evasive)."],["Unprecedented","Never having happened before."],["Negligible","So small as to be not worth considering."],["What 'but/however' signals before a blank","Contrast — expect the blank to reverse the previous direction."],["Vocab prediction method","Cover choices, predict a plain word from context, then match tone and meaning."],["Best review rhythm for vocab","Nightly 10 minutes with spaced repetition: tomorrow, 3 days, 1 week, 2 weeks."]]},{"id":"sat-sat-test-day-tips","title":"SAT Prep: SAT Test Day Tips","topic":"SAT Prep","cards":[["Digital SAT total time","About 2 hours 14 minutes: RW 32+32 min, 10-min break, Math 35+35 min."],["Non-negotiable items to bring","Charged device with Bluebook, admission confirmation, photo ID, charger."],["Also worth bringing","Approved calculator, pencils/pen, snacks, water, light jacket."],["When to arrive","30 minutes early — check-in plus buffer, no rush."],["Night-before rule","Light review only, pack the bag, 8 hours of sleep. No new material."],["Best test-day breakfast","Protein plus slow carbs (eggs and toast) — steady glucose, no sugar crash."],["Phone policy on breaks","Off and away, always — a phone check can void your score."],["The 15-second panic reset","Long slow exhale, drop shoulders, move to the next question."],["If tech fails","Raise your hand immediately; loaners exist and answers sync as you go."],["Blank answers on test day","Never — no penalty for guessing, so always enter your best answer."]]},{"id":"sat-sat-study-schedule","title":"SAT Prep: SAT Study Schedule","topic":"SAT Prep","cards":[["First step of any SAT plan","One timed full-length Bluebook practice test to set your baseline."],["How to set a target score","Look up your colleges' middle-50% range; aim 50-100 points above baseline."],["1-week plan = ?","15-20 hours of triage on your 2-3 biggest weaknesses (~30-50 points)."],["1-month plan = ?","About 40 hours: weak sections, timed sets, 2 full simulations (~50-100 points)."],["3-month plan = ?","80-100 hours: foundations, then weekly full tests driven by error logs (150+ possible)."],["The three error categories","Content gaps · careless errors · timing losses — sort every miss into one."],["Why daily beats weekly","Spacing + streaks beat marathon sessions on retention AND consistency."],["What week 4 of the 1-month plan looks like","Two full timed simulations, light drills, taper the final 2 days."],["Month 3 of the 3-month plan","Full practice test every weekend; weekdays driven by that test's error log."],["The 'never miss two' rule","Missing one day is life; missing two starts a new habit of not studying."]]},{"id":"skills-pomodoro-technique","title":"Study Skills: Pomodoro Technique","topic":"Study Skills","cards":[["Classic Pomodoro timing","25 minutes of single-task focus, then a 5-minute break; long break after 4."],["Who invented Pomodoro?","Francesco Cirillo, late 1980s, named for his tomato-shaped kitchen timer."],["Why short sprints help you start","A visible countdown shrinks activation energy — 25 minutes is a winnable game."],["Switch cost","The focus lost every time attention jumps tasks; single-tasking avoids paying it repeatedly."],["The distraction pad","Paper where stray thoughts get parked during a sprint, handled later on breaks."],["What makes a 'real' break","Movement, water, window-gazing — rest without new information flooding in."],["Pomodoro for deep work","Lengthen sprints to 45-50 minutes with 10-minute breaks."],["Pomodoro when anxious or stuck","Shrink to 15/3 — tiny sprints lower the barrier to starting."],["Daily sprint target for a heavy study day","About 6-8 completed pomodoros; shrink the goal before quitting the system."],["Rule when interrupted mid-sprint","Inform, negotiate a later time, restart the sprint."]]},{"id":"skills-active-recall","title":"Study Skills: Active Recall","topic":"Study Skills","cards":[["What is active recall?","Studying by retrieving information from memory instead of re-exposing yourself to it."],["What is the testing effect?","Self-testing produces stronger, longer-lasting memory than re-reading — one of learning science's most replicated results."],["Why re-reading feels good but fails","It creates the fluency illusion: familiarity mistaken for knowledge."],["The brain dump","Blank page + write all you remember + repair gaps in another color."],["The question sandwich","Read closed-book questions you wrote, answer from memory, check."],["Desirable difficulty","Effortful retrieval that feels harder but builds stronger memory."],["Flashcard honesty rule","Always make a real retrieval attempt (10-15 sec) before flipping."],["Why teach-it-out-loud works","Hesitations and vague spots mark exactly where your gaps are."],["What is an error log?","A one-line-per-miss list of failed retrievals — your precise review agenda."],["Recognition vs recall","Recognizing a correct answer vs producing it from nothing; exams demand recall."]]},{"id":"skills-spaced-repetition","title":"Study Skills: Spaced Repetition","topic":"Study Skills","cards":[["What is spaced repetition?","Reviewing at expanding intervals so each review lands just before you'd forget."],["What is the forgetting curve?","Memory's steep decay over time — most new learning fades within 24-48 hours untouched."],["Who discovered the forgetting curve?","Hermann Ebbinghaus, in the 1880s, by testing his own memory with nonsense syllables."],["Effect of each well-timed review","Roughly doubles how long the memory survives — the curve gets flatter each time."],["Beginner interval ladder","Learn → 1 day → 3 days → 1 week → 2 weeks → monthly."],["What happens to a missed card's interval?","It resets short (e.g., tomorrow) until you reconsolidate it."],["Cramming vs spacing","Cramming fills short-term memory for tomorrow; spacing builds durable memory for the semester."],["StudyBonk's role in spacing","It schedules the intervals automatically and builds each day's due queue for you."],["Why shuffle decks?","Predictable order turns recall into recognition — shuffling keeps retrieval honest."],["Spacing for finals","Start 3-4 weeks out with rotating daily review; finals become review, not re-learning."]]},{"id":"skills-note-taking-methods","title":"Study Skills: Note-Taking Methods","topic":"Study Skills","cards":[["Cornell page zones","Cue column (left), notes area (right), summary strip (bottom)."],["When to fill the cue column","Within 24 hours after class, with questions your notes answer."],["Outline method is best for","Hierarchical, structured material — history and biology lectures."],["Mind map is best for","Seeing connections: systems, brainstorming, big-picture relationships."],["Charting method is best for","Topics that repeat the same categories (compare/contrast-heavy subjects)."],["Math notes should feature","Worked examples plus a blank column for step-by-step reasoning, filled later."],["The transcript trap","Verbatim copying that records words without processing ideas."],["The 24-hour rule","Revisit, complete and cue your notes within a day of taking them."],["Personal shorthand examples","b/c (because), w/ (with), → (leads to), + (and) — defined once, used forever."],["Best way to STUDY from notes","Cover the notes, recall from cues, check — active recall, never rereading."]]},{"id":"skills-exam-anxiety","title":"Study Skills: Exam Anxiety","topic":"Study Skills","cards":[["Why anxiety makes you blank","Fight-or-flight borrows working memory — the workspace recall needs."],["Yerkes-Dodson principle","Performance peaks at moderate arousal; both extremes hurt."],["The physiological sigh","Two quick nose inhales, one long mouth exhale — fastest known calm-down."],["Box breathing pattern","In 4, hold 4, out 4, hold 4."],["Grounding 5-4-3-2-1","Name 5 things you see, 4 you feel, 3 you hear, 2 you smell, 1 you taste."],["Reappraisal","Relabel nerves as readiness: 'my body is fueling me' beats forcing calm."],["The first-five-minutes card","A rehearsed opening routine that outpaces panic's organizing window."],["Why simulate test conditions","Each rehearsal strips an unknown — and unknowns are what panic feeds on."],["Night-before rule","Early stop, pack everything, protect sleep — cramming trades clarity for noise."],["The post-test rule","No post-mortem: the score is data, not identity."]]},{"id":"skills-memory-techniques","title":"Study Skills: Memory Techniques","topic":"Study Skills","cards":[["Why does vivid imagery work?","Brains remember images, stories and spaces far better than abstract lists — novelty and connection add retrieval handles."],["Acronym vs acrostic","Acronym: initials form a word (HOMES). Acrostic: initials begin the words of a sentence (My Very Educated Mother...)."],["What is a memory palace?","Vivid images placed along a familiar spatial route; recall by mentally walking the route."],["Memory palace step 1","Choose a place you know cold and fix a route of 5-10 stations."],["Memory palace step 2","Place one big, weird, interactive image per station for each item."],["What is chunking?","Grouping items into meaningful units so each working-memory slot holds more."],["Working memory capacity","About 4 chunks at once — the bottleneck all techniques route around."],["What is elaborative encoding?","Connecting new material to images, stories or knowledge — every connection is a retrieval handle."],["Best mnemonic strategy","Make your own, make it weird/personal — creation and strangeness both strengthen encoding."],["How techniques become permanent","Marry them to spaced repetition: build once, review tomorrow and next week."]]}],"quizzes":[{"id":"math-algebra-basics","title":"Math: Algebra Basics","topic":"Math","questions":[{"q":"Simplify: 7x + 4 − 3x","choices":["4x + 4","10x + 4","4x − 4","7x + 1"],"answer":0,"explain":"Combine the like terms 7x and −3x to get 4x. The +4 has no variable, so it stays: 4x + 4."},{"q":"Solve for x: 2x + 6 = 14","choices":["x = 4","x = 10","x = 3","x = 8"],"answer":0,"explain":"Subtract 6 from both sides: 2x = 8. Divide both sides by 2: x = 4. Check: 2(4) + 6 = 14 ✓."},{"q":"In the expression 5y − 3, what is the coefficient?","choices":["5","y","−3","2"],"answer":0,"explain":"The coefficient is the number attached to the variable: 5 in 5y."},{"q":"Which pair are like terms?","choices":["3x and 3x²","4a and 4b","−2x and 9x","5 and 5x"],"answer":2,"explain":"Like terms need identical variable parts. −2x and 9x are both x-to-the-first-power terms, so they combine to 7x."}]},{"id":"math-fractions-decimals-percents","title":"Math: Fractions, Decimals & Percents","topic":"Math","questions":[{"q":"What is 3/4 as a percent?","choices":["34%","75%","43%","0.75%"],"answer":1,"explain":"3 ÷ 4 = 0.75, and 0.75 as a percent is 75%. (Or: 3/4 × 100/1 = 300/4 = 75.)"},{"q":"Calculate: 2/3 + 1/6","choices":["3/9","5/6","3/6","2/9"],"answer":1,"explain":"Common denominator 6: 2/3 = 4/6. Then 4/6 + 1/6 = 5/6."},{"q":"A $40 shirt is 25% off. What's the sale price?","choices":["$35","$30","$25","$32"],"answer":1,"explain":"25% of 40 = 0.25 × 40 = $10 off. Sale price = 40 − 10 = $30. (Shortcut: 25% off means you pay 75%: 0.75 × 40 = 30.)"},{"q":"Divide: 1/2 ÷ 1/4","choices":["1/8","2","1/2","3/4"],"answer":1,"explain":"Keep, change, flip: 1/2 × 4/1 = 4/2 = 2. Makes sense: two quarters fit in a half."}]},{"id":"math-geometry-fundamentals","title":"Math: Geometry Fundamentals","topic":"Math","questions":[{"q":"Two angles of a triangle are 55° and 65°. What's the third?","choices":["70°","60°","80°","120°"],"answer":1,"explain":"Triangle angles sum to 180°: 180 − 55 − 65 = 60°."},{"q":"Right triangle legs are 9 and 12. Hypotenuse?","choices":["15","21","13","16"],"answer":0,"explain":"81 + 144 = 225, and √225 = 15. (It's the 3-4-5 triple × 3.)"},{"q":"Area of a triangle with base 10, height 6?","choices":["60","30","16","36"],"answer":1,"explain":"A = ½bh = ½(10)(6) = 30. Forgetting the ½ (answering 60) is the classic error."},{"q":"Circle radius 3 — circumference?","choices":["6π","3π","9π","π/3"],"answer":0,"explain":"C = 2πr = 2π(3) = 6π ≈ 18.8. (9π is the area — don't swap the formulas.)"}]},{"id":"math-trigonometry-essentials","title":"Math: Trigonometry Essentials","topic":"Math","questions":[{"q":"In a right triangle, the side across from your angle is 3 and the hypotenuse is 5. What ratio is this?","choices":["sin θ = 3/5","cos θ = 3/5","tan θ = 3/5","sin θ = 5/3"],"answer":0,"explain":"Opposite over hypotenuse is the definition of sine: sin θ = 3/5 = 0.6."},{"q":"tan θ = 1. What is θ?","choices":["30°","45°","60°","90°"],"answer":1,"explain":"tan 45° = opp/adj = 1 because the 45-45-90 triangle's legs are equal. θ = tan⁻¹(1) = 45°."},{"q":"You know the angle and the adjacent side, and need the hypotenuse. Use:","choices":["sin","cos","tan","Pythagorean theorem"],"answer":1,"explain":"Cosine links adjacent and hypotenuse: cos θ = adj/hyp. Pythagoras needs two sides, not an angle."},{"q":"Sides of a 30-60-90 triangle, shortest side = 4. Hypotenuse?","choices":["4√3","8","8√3","6"],"answer":1,"explain":"30-60-90 is 1 : √3 : 2, so the hypotenuse is double the shortest side: 4 × 2 = 8."}]},{"id":"math-linear-equations-graphing","title":"Math: Linear Equations & Graphing","topic":"Math","questions":[{"q":"What is the slope of y = −3x + 7?","choices":["7","−3","3","−7"],"answer":1,"explain":"In y = mx + b, m is the coefficient of x: here m = −3. The line falls 3 units per step right."},{"q":"Slope through (2, 5) and (6, 13)?","choices":["2","8","1/2","−2"],"answer":0,"explain":"m = (13 − 5)/(6 − 2) = 8/4 = 2."},{"q":"Where does y = 2x + 4 cross the y-axis?","choices":["(0, 4)","(4, 0)","(0, 2)","(2, 0)"],"answer":0,"explain":"The y-intercept is b = 4, at the point (0, 4) — x is always 0 on the y-axis."},{"q":"Solve: x + y = 5 and x − y = 1","choices":["x = 3, y = 2","x = 2, y = 3","x = 4, y = 1","x = 1, y = 4"],"answer":0,"explain":"Add the equations: 2x = 6 → x = 3. Then 3 + y = 5 → y = 2. Check both: 3+2=5 ✓, 3−2=1 ✓."}]},{"id":"math-word-problems-strategies","title":"Math: Word Problem Strategies","topic":"Math","questions":[{"q":"Translate: 'seven less than twice a number is 19'","choices":["2x − 7 = 19","7 − 2x = 19","2(x − 7) = 19","2x = 19 − 7"],"answer":0,"explain":"'Twice a number' = 2x; 'seven less than' that = 2x − 7; 'is' = equals. Watch the reversal trap: 7 − 2x is wrong."},{"q":"A shirt costs $x. It's on sale for 25% off. The sale price expression is:","choices":["0.25x","x − 0.25","0.75x","x/25"],"answer":2,"explain":"25% off means you pay 75%: 0.75x. Or compute x − 0.25x = 0.75x. (x − 0.25 subtracts 25 cents, not 25 percent.)"},{"q":"Two consecutive even integers sum to 46. The smaller one is:","choices":["22","23","24","20"],"answer":0,"explain":"x + (x + 2) = 46 → 2x = 44 → x = 22. Check: 22 + 24 = 46 ✓. Even integers step by 2."},{"q":"You answer 'x = 5 books' but books are sold in packs shown as $12 each. Best sanity check?","choices":["Re-read what the question actually asked for","Move to the next problem immediately","Erase and start over completely","Change 5 to a bigger number"],"answer":0,"explain":"Most word-problem misses are answering the wrong quantity (books vs dollars). Re-reading the question sentence is the fastest check."}]},{"id":"biology-cell-basics","title":"Biology: Cell Basics","topic":"Biology","questions":[{"q":"Which organelle stores DNA and controls the cell's activities?","choices":["Ribosome","Nucleus","Mitochondrion","Vacuole"],"answer":1,"explain":"The nucleus is the control center: it stores DNA and directs everything the cell does. Mitochondria handle energy and ribosomes build proteins, but neither stores DNA (in eukaryotes)."},{"q":"A cell is surrounded by liquid. Which structure decides what enters and leaves?","choices":["Cell wall","Nucleus","Vacuole","Cell membrane"],"answer":3,"explain":"The cell membrane is the gatekeeper — a flexible boundary that controls what gets in and out. The cell wall is a rigid extra layer for support, found in plants but not animals."},{"q":"Which pair correctly matches an organism to its cell type?","choices":["Bacteria — prokaryote","Bacteria — eukaryote","Human — prokaryote","Mushroom — prokaryote"],"answer":0,"explain":"Bacteria are prokaryotes: no nucleus, DNA floating in the cytoplasm. Humans and mushrooms (a fungus) are eukaryotes — anything big enough to see without a microscope is."},{"q":"A plant is kept in complete darkness for a week. Which organelle is directly out of work?","choices":["Mitochondrion","Nucleus","Chloroplast","Ribosome"],"answer":2,"explain":"Chloroplasts need light to do photosynthesis, so in darkness they sit idle. Mitochondria keep working by burning stored food — which is how the plant survives the week at all."}]},{"id":"biology-photosynthesis","title":"Biology: Photosynthesis","topic":"Biology","questions":[{"q":"Which gas do plants take in from the air for photosynthesis?","choices":["Oxygen","Carbon dioxide","Nitrogen","Hydrogen"],"answer":1,"explain":"CO2 is an input — it enters through leaf pores called stomata and gets built into glucose during the Calvin cycle. Oxygen is an output, not an input."},{"q":"Where do the light-dependent reactions take place?","choices":["In the stroma","In the mitochondria","In the thylakoid membranes","In the nucleus"],"answer":2,"explain":"Light reactions happen in the thylakoid membranes — the green stacks inside chloroplasts. The stroma is the fluid around them, home of the Calvin cycle."},{"q":"What two energy carriers does stage 1 deliver to the Calvin cycle?","choices":["ATP and NADPH","Glucose and oxygen","DNA and RNA","CO2 and water"],"answer":0,"explain":"ATP and NADPH are the charged batteries made by the light reactions. The Calvin cycle spends them to build glucose from CO2 — which is why the stages are a team."},{"q":"The oxygen released during photosynthesis comes from:","choices":["Splitting carbon dioxide","The soil","Chlorophyll breaking down","Splitting water"],"answer":3,"explain":"In the light reactions, water molecules are split to free electrons and hydrogen — and oxygen is the leftover, released as gas. Carbon dioxide keeps its oxygen; it ends up in the glucose."}]},{"id":"biology-dna-and-genetics","title":"Biology: DNA & Genetics","topic":"Biology","questions":[{"q":"In DNA, adenine (A) always pairs with:","choices":["G","C","T","A"],"answer":2,"explain":"A pairs with T and G pairs with C — always. This complementary pairing is what lets DNA copy itself so accurately."},{"q":"Two parents are both heterozygous (Tt). What fraction of offspring is predicted to show the recessive trait?","choices":["0%","25%","50%","75%"],"answer":1,"explain":"Tt x Tt gives TT, Tt, Tt, tt. Only the single tt box shows the recessive trait: 1 out of 4 = 25%. Three of four boxes (75%) show the dominant trait."},{"q":"A person's genotype is Bb, where B (brown eyes) is dominant. Their phenotype is:","choices":["Brown eyes","Blue eyes","One brown and one blue eye","Impossible to know"],"answer":0,"explain":"One dominant B allele is enough to show the trait, so Bb = brown eyes. Only bb would give blue eyes in this simple model."},{"q":"Which cross produces a predicted 50/50 split of dominant to recessive phenotypes?","choices":["TT x TT","Tt x Tt","tt x tt","Tt x tt"],"answer":3,"explain":"Tt x tt gives Tt, Tt, tt, tt — exactly half show the dominant trait, half the recessive. The heterozygous x recessive cross is the 50/50 one."}]},{"id":"biology-human-body-systems","title":"Biology: Human Body Systems","topic":"Biology","questions":[{"q":"Which system delivers oxygen and nutrients to cells all over the body?","choices":["Circulatory","Respiratory","Digestive","Nervous"],"answer":0,"explain":"The circulatory system is the delivery service: blood carries oxygen and nutrients to cells and hauls wastes away. Respiratory loads the oxygen, but circulatory ships it."},{"q":"The kidneys belong to which system?","choices":["Digestive","Endocrine","Lymphatic","Excretory"],"answer":3,"explain":"Kidneys filter blood and balance water and salts — the excretory (urinary) system's job. People guess digestive because kidneys are near the stomach; location isn't membership."},{"q":"Which two systems are the body's main control and communication networks?","choices":["Skeletal and muscular","Nervous and endocrine","Digestive and excretory","Circulatory and respiratory"],"answer":1,"explain":"Nervous = fast electrical messages; endocrine = slower chemical (hormone) messages. Together they run every other system — the body's text messages and mail service."},{"q":"Sweating when you overheat is an example of:","choices":["Disease","Digestion","Homeostasis","Cellular respiration"],"answer":2,"explain":"Sweating cools you back toward your set temperature — the definition of homeostasis. Any 'body fixes a condition' scenario points to homeostasis."}]},{"id":"biology-ecosystems","title":"Biology: Ecosystems","topic":"Biology","questions":[{"q":"In the food chain grass → rabbit → fox, the rabbit is a:","choices":["Producer","Primary consumer","Secondary consumer","Decomposer"],"answer":1,"explain":"The rabbit eats the producer (grass), making it a primary consumer (an herbivore). The fox, eating the rabbit, is the secondary consumer."},{"q":"A field's plants contain 20,000 kcal of energy. Roughly how much reaches second-level consumers?","choices":["20,000 kcal","2,000 kcal","200 kcal","20 kcal"],"answer":2,"explain":"Each step keeps about 10%: 20,000 (producers) → 2,000 (primary consumers) → 200 kcal (secondary consumers). Two steps, two divisions by ten."},{"q":"Which organism returns nutrients to the soil by breaking down dead material?","choices":["Decomposer","Herbivore","Producer","Apex predator"],"answer":0,"explain":"Decomposers (fungi and bacteria) recycle dead organisms into nutrients producers can absorb. Without them, nutrients would stay locked in dead material forever."},{"q":"A biome is hot year-round with very little rain. It is most likely a:","choices":["Tropical rainforest","Tundra","Desert","Temperate forest"],"answer":2,"explain":"Hot + dry = desert. Tropical rainforests are hot but extremely wet, and tundra is cold and dry. Temperature plus rainfall names almost any biome."}]},{"id":"biology-mitosis-vs-meiosis","title":"Biology: Mitosis vs Meiosis","topic":"Biology","questions":[{"q":"Mitosis produces:","choices":["2 identical diploid cells","4 unique haploid cells","2 unique haploid cells","4 identical diploid cells"],"answer":0,"explain":"One division, two cells, each identical to the parent with the full chromosome count. 'Four unique cells' is meiosis — the classic look-alike answer."},{"q":"Crossing over occurs during:","choices":["Mitosis","Cytokinesis","Prophase I of meiosis","Interphase"],"answer":2,"explain":"In prophase I, matching chromosomes pair up and swap segments — a major source of genetic variation. Mitosis never does this; that's why its products are identical."},{"q":"A human sperm cell contains how many chromosomes?","choices":["46","92","12","23"],"answer":3,"explain":"Sperm are haploid: half the body's 46, which is 23. Fertilization adds the egg's 23 to restore 46 in the zygote."},{"q":"Which process heals a cut on your hand?","choices":["Meiosis","Mitosis","Fertilization","Crossing over"],"answer":1,"explain":"Repair calls for identical replacement cells — mitosis. Trigger words: repair, growth, clone = mitosis; gametes, variation = meiosis."}]},{"id":"chemistry-atomic-structure","title":"Chemistry: Atomic Structure","topic":"Chemistry","questions":[{"q":"An atom has 17 protons, 18 neutrons and 17 electrons. Its mass number is:","choices":["17","18","35","52"],"answer":2,"explain":"Mass number = protons + neutrons = 17 + 18 = 35. Electrons are ignored — they're so light they barely count toward mass."},{"q":"What determines which element an atom is?","choices":["Neutron count","Proton count","Electron count","Mass number"],"answer":1,"explain":"The proton count (atomic number) is the element's identity card. Change neutrons and you get an isotope; change electrons and you get an ion; change protons and you have a different element entirely."},{"q":"Carbon-14 has how many neutrons? (Carbon's atomic number is 6.)","choices":["8","6","14","20"],"answer":0,"explain":"The 14 is the mass number: protons + neutrons. So neutrons = 14 − 6 = 8. Carbon-12 would have 12 − 6 = 6 neutrons."},{"q":"An atom that gains electrons becomes:","choices":["A different element","A positive ion","An isotope","A negative ion"],"answer":3,"explain":"Extra electrons bring extra negative charge — a negative ion (anion). Losing electrons leaves more protons than electrons, making a positive ion (cation). The element never changes."}]},{"id":"chemistry-periodic-table","title":"Chemistry: Periodic Table","topic":"Chemistry","questions":[{"q":"Elements in the same group of the periodic table share the same number of:","choices":["Protons","Valence electrons","Neutrons","Electron shells"],"answer":1,"explain":"Groups are columns, and column-mates have matching valence electron counts — which is exactly why they react similarly. Electron shells match within a period (a row), not a group."},{"q":"Which group is famously unreactive because its outer shells are already full?","choices":["Group 1","Group 2","Group 17","Group 18"],"answer":3,"explain":"Group 18, the noble gases (helium, neon, argon...), have full outer shells. With nothing to gain or lose, they rarely bond — the introverts of the table."},{"q":"Moving left to right across a period, atomic radius generally:","choices":["Increases","Decreases","Stays the same","Doubles"],"answer":1,"explain":"Each step right adds a proton, and the stronger pull drags electrons closer — atoms shrink across a row. Down a column they grow, because new shells get added."},{"q":"An element in Group 1, with 1 valence electron, will most likely:","choices":["Gain 7 electrons","Share 4 electrons","Lose 1 electron","Do nothing"],"answer":2,"explain":"Losing its single valence electron empties the outer shell, exposing the full shell beneath — the easy path. That's why alkali metals form +1 ions so eagerly."}]},{"id":"chemistry-chemical-bonding","title":"Chemistry: Chemical Bonding","topic":"Chemistry","questions":[{"q":"A bond formed when one atom transfers electrons to another is:","choices":["Covalent","Metallic","Ionic","Polar"],"answer":2,"explain":"Transfer = ionic. The giver becomes a positive ion, the taker negative, and their attraction forms the bond. Sharing is covalent; pooling is metallic."},{"q":"Which compound is most likely covalent?","choices":["H2O","NaCl","MgO","KBr"],"answer":0,"explain":"H2O bonds hydrogen to oxygen — both nonmetals — so they share: covalent. The other three all pair a metal with a nonmetal, the ionic signature."},{"q":"Metals conduct electricity because:","choices":["Their electrons are locked in fixed orbits","Their valence electrons flow freely through the structure","They are ionic crystals","They contain noble gases"],"answer":1,"explain":"In metallic bonding, valence electrons detach from individual atoms and roam the whole metal — a sea of electrons. Moving charge is exactly what conduction is."},{"q":"When an atom loses electrons, it becomes:","choices":["A negative ion","A neutral atom","An isotope","A positive ion"],"answer":3,"explain":"Losing negative electrons leaves more positive protons than electrons — a positive ion (cation). Gaining electrons makes a negative ion (anion); the element itself never changes."}]},{"id":"chemistry-chemical-reactions","title":"Chemistry: Chemical Reactions","topic":"Chemistry","questions":[{"q":"What is the balanced form of H2 + O2 → H2O?","choices":["H2 + O2 → H2O","2H2 + O2 → 2H2O","H2 + 2O2 → 2H2O","2H2 + 2O2 → 2H2O"],"answer":1,"explain":"Left side has 2 H and 2 O, so we need 2 H2O on the right (4 H, 2 O) — which forces 2H2 on the left. Check: 4 H and 2 O on both sides. Balanced."},{"q":"CaCO3 → CaO + CO2 is what type of reaction?","choices":["Synthesis","Combustion","Decomposition","Double replacement"],"answer":2,"explain":"One compound breaks into two products — the decomposition silhouette (1 → 2). Two things joining would be synthesis."},{"q":"In a balanced equation, the number of atoms of each element:","choices":["Is equal on both sides","Is always greater in the reactants","Is always greater in the products","Doesn't matter"],"answer":0,"explain":"Conservation of mass demands it: atoms can't be created or destroyed, so every element must match left and right. That's the definition of balanced."},{"q":"Which observation is a sign that a chemical reaction occurred?","choices":["Ice melting","Water evaporating","Sugar dissolving in tea","A solid forming when two clear solutions mix"],"answer":3,"explain":"A new solid from two solutions is a precipitate — evidence of a new substance. Melting, evaporating and dissolving are physical changes: same substance, different form."}]},{"id":"chemistry-moles-and-stoichiometry","title":"Chemistry: Moles & Stoichiometry","topic":"Chemistry","questions":[{"q":"One mole of any substance contains how many particles?","choices":["6.022 × 10²³","12","3.14 × 10⁸","100"],"answer":0,"explain":"Avogadro's number: 6.022 × 10²³ particles per mole — true for atoms, molecules or ions, of any substance. That's the definition of the mole."},{"q":"What is the molar mass of H2O? (H = 1.008, O = 16.00)","choices":["17.01 g/mol","18.02 g/mol","16.00 g/mol","33.02 g/mol"],"answer":1,"explain":"Two hydrogens and one oxygen: 2(1.008) + 16.00 = 2.016 + 16.00 = 18.02 g/mol. Forgetting to double the hydrogen gives the classic wrong answer, 17.01."},{"q":"How many moles are in 88.02 g of CO2 (molar mass 44.01 g/mol)?","choices":["0.5 mol","44.01 mol","2 mol","4 mol"],"answer":2,"explain":"Moles = grams ÷ molar mass = 88.02 ÷ 44.01 = 2 mol. The units tell you to divide: grams over grams-per-mole leaves plain moles."},{"q":"In N2 + 3H2 → 2NH3, how many moles of NH3 form from 3 moles of N2 (with plenty of H2)?","choices":["2","3","4","6"],"answer":3,"explain":"The ratio N2:NH3 is 1:2. Three moles of N2 × (2 NH3 / 1 N2) = 6 moles of ammonia. Read coefficients as a recipe and scale it."}]},{"id":"chemistry-acids-and-bases","title":"Chemistry: Acids & Bases","topic":"Chemistry","questions":[{"q":"A solution has a pH of 3. It is:","choices":["Basic","Neutral","Acidic","A salt"],"answer":2,"explain":"Anything below 7 on the pH scale is acidic — and pH 3 is strongly acidic. Neutral is exactly 7; above 7 is basic."},{"q":"What are the two products of a neutralization reaction?","choices":["Salt and water","Two acids","Hydrogen gas and salt","Water and oxygen"],"answer":0,"explain":"The acid's H+ joins the base's OH− to make water, and the leftover ions form a salt: acid + base → salt + water, no exceptions in this course."},{"q":"How many times more acidic is pH 2 than pH 5?","choices":["3","30","100","1,000"],"answer":3,"explain":"Three pH steps (2→3→4→5), each worth a factor of 10: 10 × 10 × 10 = 1,000 times more acidic. pH differences multiply, never add."},{"q":"Which everyday substance is a base?","choices":["Lemon juice","Baking soda","Vinegar","Soda"],"answer":1,"explain":"Baking soda (sodium bicarbonate) is a mild base — that's why it calms acidic stomachs. Lemon juice, vinegar and soda are all acids."}]},{"id":"physics-motion-and-forces","title":"Physics: Motion and Forces","topic":"Physics","questions":[{"q":"A cyclist rides 120 meters in 20 seconds. Average speed?","choices":["6 m/s","100 m/s","2,400 m/s","0.17 m/s"],"answer":0,"explain":"Speed = distance ÷ time = 120 ÷ 20 = 6 m/s. The huge and tiny choices are unit traps from multiplying or inverting."},{"q":"Net force on a 3 kg cart accelerating at 4 m/s²?","choices":["7 N","0.75 N","12 N","1.33 N"],"answer":2,"explain":"F = ma = 3 × 4 = 12 N. The other answers come from adding (7) or dividing (0.75) instead of multiplying."},{"q":"You push a heavy box but it doesn't move. The forces on it are:","choices":["Unbalanced, so it accelerates","Balanced — your push is matched by friction","Zero — no forces act","Reversed by gravity"],"answer":1,"explain":"No motion means no change in motion, so the net force is zero: friction pushes back exactly as hard as you push. That's Newton's first law in action."},{"q":"A rocket pushes exhaust gas downward; the gas pushes the rocket upward. Which law?","choices":["First law","Second law","Third law","Law of gravity"],"answer":2,"explain":"Equal-and-opposite force pairs are Newton's third law. The rocket rises because it pushes gas down and the gas pushes back up."}]},{"id":"physics-energy-work-power","title":"Physics: Energy, Work and Power","topic":"Physics","questions":[{"q":"Kinetic energy of a 4 kg ball moving at 3 m/s?","choices":["18 J","12 J","36 J","6 J"],"answer":0,"explain":"KE = ½mv² = ½ × 4 × 3² = ½ × 4 × 9 = 18 J. Forgetting the ½ (36 J) or squaring wrongly (12 J) are the classic slips."},{"q":"Potential energy of a 2 kg book on a 3 m shelf? (Use g ≈ 10 m/s².)","choices":["6 J","20 J","60 J","15 J"],"answer":2,"explain":"PE = mgh = 2 × 10 × 3 = 60 J. Multiplying only two of the three quantities gives the trap answers."},{"q":"A ball rolls off a table. As it falls, potential energy turns into:","choices":["Kinetic energy","More potential energy","Nothing — it's lost","Chemical energy"],"answer":0,"explain":"Height drops, speed rises: PE converts to KE. Energy isn't lost — it's transformed, per conservation of energy."},{"q":"You do 600 J of work in 12 s. Your power output is:","choices":["5 W","50 W","72 W","7,200 W"],"answer":1,"explain":"P = W/t = 600 ÷ 12 = 50 W. Multiplying instead of dividing gives 7,200 W — check units to catch it."}]},{"id":"physics-waves-and-sound","title":"Physics: Waves and Sound","topic":"Physics","questions":[{"q":"A wave has frequency 10 Hz and wavelength 2 m. Its speed is:","choices":["20 m/s","5 m/s","12 m/s","0.2 m/s"],"answer":0,"explain":"v = fλ = 10 × 2 = 20 m/s. Dividing instead of multiplying gives 5 m/s — the most common slip."},{"q":"The distance from one crest to the next crest is the wave's:","choices":["Amplitude","Wavelength","Frequency","Period"],"answer":1,"explain":"Crest-to-crest distance is wavelength (λ). Amplitude is measured from the rest position to a crest, not crest to crest."},{"q":"An ambulance passes you and the siren's pitch drops. This is:","choices":["Reflection","Refraction","The Doppler effect","Resonance"],"answer":2,"explain":"As the siren moves away, each sound wave starts farther from you, so waves arrive less often — lower frequency, lower pitch. That's the Doppler effect."},{"q":"Sound cannot travel through space because:","choices":["Space is too cold","Sound is too fast","Light waves block it","Sound needs a medium, and space is nearly empty"],"answer":3,"explain":"Sound is a vibration of matter. With almost no air or anything else to vibrate, there's nothing to carry it — movie explosions are artistic license."}]},{"id":"physics-electricity-basics","title":"Physics: Electricity Basics","topic":"Physics","questions":[{"q":"A 9 V battery is connected across a 3 Ω resistor. The current is:","choices":["27 A","3 A","6 A","0.33 A"],"answer":1,"explain":"I = V/R = 9 ÷ 3 = 3 A. Multiplying instead of dividing gives 27 A — a units check catches it (volts ÷ ohms = amps)."},{"q":"Current is measured in:","choices":["Volts","Ohms","Amperes","Joules"],"answer":2,"explain":"Current — the flow of charge — is measured in amperes (A). Volts push, ohms resist, joules measure energy."},{"q":"One bulb burns out in a series circuit. The other bulbs:","choices":["Stay lit","Go dark — the only path is broken","Get brighter","Flash on and off"],"answer":1,"explain":"A series circuit has a single path. One gap stops the current everywhere — that's why one dead bulb killed the whole old-style Christmas light string."},{"q":"Which change increases the current in a circuit?","choices":["Adding more resistance","Using a longer, thinner wire","Removing the battery","Increasing the voltage"],"answer":3,"explain":"By V = IR, current rises with voltage and falls with resistance. Thinner, longer wires add resistance, and removing the battery removes the push entirely."}]},{"id":"physics-magnetism","title":"Physics: Magnetism","topic":"Physics","questions":[{"q":"Which pair of magnetic poles attracts each other?","choices":["North and north","South and south","North and south","North and plastic"],"answer":2,"explain":"Opposite poles attract; like poles repel. Plastic isn't magnetic at all, so nothing happens there."},{"q":"Best way to make an electromagnet stronger?","choices":["More coils and more current","Fewer coils","A plastic core","Less current"],"answer":0,"explain":"Strength scales with turns of wire, current and core quality. More coils and more current push all the levers the right way."},{"q":"A compass needle points north because:","choices":["The needle is painted red","Earth has a magnetic field","Wind pushes the needle","The needle follows the sun"],"answer":1,"explain":"The needle is a tiny magnet, and Earth's churning molten iron core generates a planet-scale magnetic field that the needle aligns with."},{"q":"In a motor, what flips the current direction every half-turn?","choices":["The battery","The magnet","The coil of wire","The commutator"],"answer":3,"explain":"The commutator is a split-ring contact that reverses the current just as the loop would otherwise stall — that's what keeps the rotation going in one direction."}]},{"id":"physics-light-and-optics","title":"Physics: Light and Optics","topic":"Physics","questions":[{"q":"Light hits a flat mirror at 35° from the normal. The reflected ray leaves at:","choices":["35° from the normal","55° from the normal","70° from the surface","45° from the normal"],"answer":0,"explain":"Law of reflection: the angle of incidence equals the angle of reflection. Measure both from the normal, not the surface, and 35° in means 35° out."},{"q":"Light passes from air into water. It bends:","choices":["Away from the normal","Toward the normal","Not at all","Straight back into the air"],"answer":1,"explain":"Water is a slower medium for light, so the light bends toward the normal — that's why a straw looks kinked at the surface."},{"q":"A magnifying glass is a:","choices":["Concave lens","Plane mirror","Convex lens","Prism"],"answer":2,"explain":"A magnifying glass is thicker in the middle — a convex lens — which converges light so objects inside the focal length look enlarged."},{"q":"A banana looks yellow because it:","choices":["Creates yellow light","Reflects yellow light and absorbs the rest","Absorbs yellow light","Refracts yellow light"],"answer":1,"explain":"Object color = reflected light. The banana's surface reflects yellow wavelengths to your eye and absorbs most of the others."}]},{"id":"history-ancient-civilizations","title":"History: Ancient Civilizations","topic":"History","questions":[{"q":"The world's first writing system developed in:","choices":["Rome","Mesopotamia","Greece","Persia"],"answer":1,"explain":"Sumerian scribes in Mesopotamia pressed cuneiform into clay around 3200 BCE — the first writing we know of. Egypt's hieroglyphics followed soon after."},{"q":"Athenian democracy is best described as:","choices":["Rule by a pharaoh","Rule by kings","Citizens voting directly on laws","Rule by generals"],"answer":2,"explain":"In Athens, citizens assembled and voted on laws themselves — direct democracy. But 'citizens' excluded women, enslaved people and foreigners, so a minority actually voted."},{"q":"Rome's early government, with elected leaders and a Senate and no king, was a:","choices":["Democracy","Republic","Monarchy","Dynasty"],"answer":1,"explain":"From 509 BCE Rome was a republic: power held by elected magistrates and the Senate. It became an empire only after Augustus in 27 BCE."},{"q":"Hammurabi's Code is famous as:","choices":["An early written set of laws","Epic poems about the gods","Maps of the Nile","Records of the Olympic games"],"answer":0,"explain":"Hammurabi's Code (Babylon, ~1750 BCE) was one of history's first written law codes — laws publicly displayed so everyone knew the rules and punishments."}]},{"id":"history-american-revolution","title":"History: American Revolution","topic":"History","questions":[{"q":"'No taxation without representation' protested:","choices":["British taxes on colonists who had no vote in Parliament","Taxes paid by Britain itself","Church taxes in Virginia","Spanish trade tariffs"],"answer":0,"explain":"Parliament taxed the colonies to pay war debt, but the colonies sent no representatives to Parliament. The money was secondary — the lack of a voice was the grievance."},{"q":"The Declaration of Independence was adopted in:","choices":["1775","1776","1781","1783"],"answer":1,"explain":"July 4, 1776 — more than a year after the fighting started at Lexington, and seven years before the Treaty of Paris made independence official."},{"q":"Which victory convinced France to ally with the United States?","choices":["Yorktown","Lexington","Saratoga","Bunker Hill"],"answer":2,"explain":"Saratoga (1777) proved the Americans could beat a full British army. France took that as evidence the rebellion was worth backing — and French power decided the endgame at Yorktown."},{"q":"The Treaty of Paris of 1783:","choices":["Started the French alliance","Imposed new taxes on tea","Wrote the Constitution","Ended the war and recognized US independence"],"answer":3,"explain":"The 1783 Treaty of Paris ended the war: Britain recognized independence and set US borders at the Mississippi River. The Constitution came four years later, in 1787."}]},{"id":"history-world-war-i","title":"History: World War I","topic":"History","questions":[{"q":"Which is NOT one of the MAIN causes of World War I?","choices":["Militarism","Alliances","Isolationism","Nationalism"],"answer":2,"explain":"MAIN = Militarism, Alliances, Imperialism, Nationalism. Isolationism — staying out of foreign conflicts — is closer to the opposite of the alliance system that spread the war."},{"q":"The spark that started World War I was:","choices":["The invasion of Poland","The assassination of Archduke Franz Ferdinand","The bombing of Pearl Harbor","The Berlin Blockade"],"answer":1,"explain":"In June 1914 a Serbian nationalist killed the heir to Austria-Hungary's throne in Sarajevo. Alliances then dragged Europe into war within weeks."},{"q":"The US entered WWI in 1917 largely because of:","choices":["Unrestricted submarine warfare and the Zimmermann Telegram","The Treaty of Versailles","The fall of the Berlin Wall","Its alliance with Austria-Hungary"],"answer":0,"explain":"German U-boats sank civilian and American ships (like the Lusitania), and the Zimmermann Telegram revealed Germany offering Mexico US territory. Together they ended US neutrality."},{"q":"The Treaty of Versailles:","choices":["Made Germany an equal partner in Europe","Created the United Nations","Blamed Germany and imposed massive reparations","Was signed only by Germany and Russia"],"answer":2,"explain":"Versailles (1919) forced Germany to accept war guilt, lose territory, cap its military and pay crushing reparations — punishments whose backlash helped cause WWII."}]},{"id":"history-world-war-ii","title":"History: World War II","topic":"History","questions":[{"q":"World War II in Europe began when Germany:","choices":["Invaded Poland in September 1939","Bombed Pearl Harbor","Built the Berlin Wall","Signed the Treaty of Versailles"],"answer":0,"explain":"Germany invaded Poland on September 1, 1939; Britain and France declared war two days later. Pearl Harbor (1941) came later and brought in the US."},{"q":"The US entered WWII after:","choices":["D-Day","The attack on Pearl Harbor, December 7, 1941","The Battle of Britain","The Munich agreement"],"answer":1,"explain":"Japan's surprise attack on Pearl Harbor killed about 2,400 Americans and ended US neutrality overnight — Congress declared war the next day."},{"q":"D-Day, June 6, 1944, was:","choices":["Japan's final surrender","The bombing of Berlin","The Allied invasion of Normandy, France","The start of US neutrality"],"answer":2,"explain":"D-Day was history's largest seaborne invasion: Allied forces landed on five Normandy beaches, opening the western front that liberated France and Western Europe."},{"q":"After the war, the Allies created the ___ to keep the peace.","choices":["League of Nations","United Nations","Warsaw Pact","Marshall Plan"],"answer":1,"explain":"The United Nations (1945) replaced the failed League of Nations — and this time the US joined, giving it real strength."}]},{"id":"history-cold-war","title":"History: Cold War","topic":"History","questions":[{"q":"Containment was the US policy of:","choices":["Stopping the spread of communism","Fighting the USSR directly","Rebuilding Japan","Ending World War II"],"answer":0,"explain":"Containment meant blocking communism's expansion anywhere it appeared — through aid (Truman Doctrine, Marshall Plan), alliances (NATO) and proxy wars (Korea, Vietnam), never direct war with the USSR."},{"q":"During the Berlin Airlift, the US and Britain:","choices":["Attacked East Germany","Flew supplies into West Berlin past the Soviet blockade","Built the Berlin Wall","Invaded Cuba"],"answer":1,"explain":"When the USSR blockaded West Berlin in 1948–49, western planes flew in food, fuel and medicine for almost a year until the blockade ended — the first major Cold War standoff, won without a shot."},{"q":"The Cuban Missile Crisis happened in:","choices":["1948","1953","1961","1962"],"answer":3,"explain":"In October 1962, US spy planes found Soviet nuclear missiles being built in Cuba. Thirteen days of brinkmanship ended with the missiles withdrawn — the closest the world has come to nuclear war."},{"q":"The Soviet Union dissolved in:","choices":["1989","1985","1991","1975"],"answer":2,"explain":"The Berlin Wall fell in 1989, Germany reunified in 1990, and in December 1991 the USSR itself broke apart into 15 independent countries — the Cold War's endpoint."}]},{"id":"history-civil-rights-movement","title":"History: Civil Rights Movement","topic":"History","questions":[{"q":"Brown v. Board of Education (1954) ruled that:","choices":["Voting tests must end","Buses must desegregate","School segregation is unconstitutional","Segregated lunch counters are illegal"],"answer":2,"explain":"Brown struck down school segregation, declaring separate schools 'inherently unequal' — overturning 'separate but equal' in education. The other battles came later."},{"q":"Rosa Parks sparked the Montgomery Bus Boycott by:","choices":["Refusing to give up her bus seat","Leading a lunch-counter sit-in","Founding the NAACP","Suing a school district"],"answer":0,"explain":"Her December 1955 arrest for refusing to give up her seat triggered a 381-day boycott that ended with desegregated buses — and launched MLK into national leadership."},{"q":"The Civil Rights Act of 1964:","choices":["Ended slavery","Banned segregation in public places and employment discrimination","Lowered the voting age","Created the Marshall Plan"],"answer":1,"explain":"The 1964 act attacked segregation: public accommodations and job discrimination were banned nationwide. Slavery had ended in 1865, and voting rights were the 1965 act's job."},{"q":"The Voting Rights Act was passed in:","choices":["1963","1964","1965","1968"],"answer":2,"explain":"After 'Bloody Sunday' at Selma in March 1965, the Voting Rights Act passed that August — banning literacy tests and poll taxes and protecting Black voting rights."}]},{"id":"sat-sat-reading-strategies","title":"SAT Prep: SAT Reading Strategies","topic":"SAT Prep","questions":[{"q":"The digital SAT Reading & Writing section gives you approximately how long per question?","choices":["45 seconds","About 71 seconds","2 minutes","3 minutes"],"answer":1,"explain":"54 questions in 64 minutes works out to about 71 seconds each. Knowing your real budget — not a vague feeling — is the first step to finishing."},{"q":"You're 40 seconds over budget on one question. Best move?","choices":["Keep working until you solve it no matter what","Pick a random answer and forget it forever","Flag it, make your best guess, and move on to bank time","Skip it without marking anything"],"answer":2,"explain":"Flag + guess + move is the two-pass way: your guess might be right, the flag brings you back, and the easy questions ahead are where your points are."},{"q":"An inference question's correct answer is the one that:","choices":["requires outside knowledge of the topic","follows one small step from what the passage states","makes the strongest, boldest claim available","restates the passage word for word"],"answer":1,"explain":"SAT inferences are tiny steps from stated text, not leaps. A word-for-word restatement is usually a detail-question answer, and bold claims are classic traps."},{"q":"A choice says the author 'completely disproves' an opposing theory, but the passage only raises one doubt. This choice is:","choices":["correct, because any doubt weakens a theory","wrong, because extreme language overreaches the evidence","correct, if the theory is old","irrelevant to the question"],"answer":1,"explain":"This is the classic overreach trap. The passage supports 'weakens' or 'challenges,' not 'completely disproves' — match the strength of the text exactly."}]},{"id":"sat-sat-writing-grammar","title":"SAT Prep: SAT Writing & Grammar","topic":"SAT Prep","questions":[{"q":"Which correctly joins two complete sentences?","choices":["The lab was quiet, everyone held their breath.","The lab was quiet; everyone held their breath.","The lab was quiet everyone held their breath.","The lab being quiet, everyone held their breath."],"answer":1,"explain":"A semicolon legally joins two independent clauses. Choice A is a comma splice, C is a fused sentence, and D changes the meaning of the first clause."},{"q":"'The collection of stamps (was/were) valuable.' Correct verb?","choices":["were, because stamps is plural","was, because the subject is 'collection'","were, because 'of stamps' is plural","either works"],"answer":1,"explain":"Cross out 'of stamps' — the subject is 'collection,' singular, so 'was.' The prepositional phrase is camouflage, not the subject."},{"q":"'Walking through the museum, the paintings amazed her.' What's the error?","choices":["'Walking' should be 'Walked'","The paintings were doing the walking — dangling modifier","'Amazed' should be 'amazes'","There is no error"],"answer":1,"explain":"The opening phrase describes an action, so the words after the comma must name the actor. 'Walking through the museum, she was amazed by the paintings' fixes it."},{"q":"Sentence 1: 'The trial failed.' Sentence 2: '___, the team published its data.' Best transition?","choices":["Similarly","Therefore","Nonetheless","For instance"],"answer":2,"explain":"Publishing despite failure is contrast, so 'Nonetheless' fits. 'Therefore' would mean the failure caused the publishing — backwards logic."}]},{"id":"sat-sat-math-strategies","title":"SAT Prep: SAT Math Strategies","topic":"SAT Prep","questions":[{"q":"The digital SAT math section allows a calculator:","choices":["on no questions","only in the second module","on every question","only if the proctor approves"],"answer":2,"explain":"The digital SAT permits a calculator on the entire math section — the built-in Desmos or your own approved device. The old No Calculator section is gone."},{"q":"Fastest reliable way to solve 2x + 3y = 12 and y = x + 1 on the digital SAT?","choices":["Guess and check the choices","Graph both in Desmos and click the intersection","Skip it — systems can't be graphed","Multiply everything by 12"],"answer":1,"explain":"Graphing in Desmos shows the intersection instantly — here x = 1.8, y = 2.8. Elimination works too, but the graph is faster and immune to algebra slips."},{"q":"A fill-in question says 'round your answer to the nearest tenth.' You compute 4.444... You should enter:","choices":["4.444","4","4.4","44"],"answer":2,"explain":"The instruction is part of the question. 4.444 rounded to the nearest tenth is 4.4 — ignoring rounding directions is one of the most common fill-in errors."},{"q":"You solve a rate problem and get 30, but the question asks for hours and the rate was in minutes. Best next step?","choices":["Enter 30 anyway — graders allow unit slips","Re-read the question and convert: 30 minutes = 0.5 hours","Double 30 to 60","Flag it and never return"],"answer":1,"explain":"Answer in the units the question requests. Unit mismatch is a silent point-killer — the 20-second re-read before submitting is exactly when you catch it."}]},{"id":"sat-sat-vocabulary","title":"SAT Prep: SAT Vocabulary","topic":"SAT Prep","questions":[{"q":"'Her theory was initially dismissed, but new data ___ her predictions.' Which word fits?","choices":["undermined","corroborated","mitigated","ignored"],"answer":1,"explain":"'But' signals reversal of 'dismissed,' so the data supported her predictions — corroborated. Undermined and ignored continue the dismissal; mitigated means 'made less severe.'"},{"q":"You hit a vocab word you've never seen. First move?","choices":["Pick the most impressive-sounding choice","Skip the question immediately","Predict a plain word from context before looking at choices","Choose whatever choice C says"],"answer":2,"explain":"Prediction from context is the rescue skill: cover the choices, read the surrounding logic (contrast words, examples, tone), guess a simple substitute, then match."},{"q":"'Ambivalent' most nearly means:","choices":["totally certain","having mixed feelings","openly hostile","deeply bored"],"answer":1,"explain":"Ambivalent = holding two conflicting attitudes at once (the Latin 'ambi' means both ways). It's a top SAT repeat offender — learn it with its cousin 'equivocal' and opposite 'unequivocal.'"},{"q":"A sentence reads: 'The plan was idealistic; a more ___ approach would consider the budget.' Best word:","choices":["practical","theoretical","sentimental","elaborate"],"answer":0,"explain":"The semicolon plus 'more' sets up a contrast with 'idealistic' — you need its opposite: practical (pragmatic). Contrast signals like this do most of the work in vocab-in-context questions."}]},{"id":"sat-sat-test-day-tips","title":"SAT Prep: SAT Test Day Tips","topic":"SAT Prep","questions":[{"q":"When should you arrive at the SAT test center?","choices":["Exactly at start time","30 minutes early","Two hours early","15 minutes late is fine"],"answer":1,"explain":"Arriving 30 minutes early handles check-in, seating and unexpected lines without flooding you with rush-stress hormones you'll want during the test."},{"q":"Your laptop dies mid-test. Best action?","choices":["Quietly ask a neighbor for help","Panic — the score is lost","Raise your hand immediately; proctors handle loaners and your work syncs","Finish on your phone"],"answer":2,"explain":"Proctors deal with device failures regularly, loaner devices exist, and Bluebook syncs your answers as you go. Reporting instantly is what protects your work — this is exactly why you also bring the charging cable."},{"q":"During the 10-minute break, you should:","choices":["check your phone quickly","move, snack, drink water — and leave the phone alone","keep working through it","cram grammar rules from your bag"],"answer":1,"explain":"Movement, fuel and hydration reset your body for the math half. Touching your phone during the test (breaks included) is a violation that can void your score."},{"q":"You blank on a question and feel panic rising. The 15-second reset is:","choices":["stare at the timer until calm returns","long slow exhale, drop shoulders, restart on the next question","skip the entire module","re-read the question ten times fast"],"answer":1,"explain":"A longer exhale than inhale activates the body's braking system, and moving to the next question rebuilds momentum. Speed re-reading just feeds the spiral."}]},{"id":"sat-sat-study-schedule","title":"SAT Prep: SAT Study Schedule","topic":"SAT Prep","questions":[{"q":"The correct first step of any SAT study schedule is:","choices":["memorize 500 vocabulary words","take a timed full-length practice test to set a baseline","buy the thickest prep book","drill the hardest practice questions available"],"answer":1,"explain":"The baseline test tells you your gap, your weak sections and your error types — everything a plan should be built from. Studying without it is guessing at the target."},{"q":"You have exactly one week before the SAT. Your plan should focus on:","choices":["learning every topic from scratch","triage: your 2-3 biggest, most fixable weaknesses","resting completely","taking a practice test every single day"],"answer":1,"explain":"One week is triage time: fix the biggest leaks (grammar rules, formulas, pacing) for the most reliable 30-50 points. Foundations-from-scratch needs the 1-3 month plans."},{"q":"How many hours does a typical 1-month SAT plan involve?","choices":["About 10 hours","About 40 hours","About 120 hours","500+ hours"],"answer":1,"explain":"Roughly 40 hours — about an hour a day plus weekend practice tests. That's typically enough for a 50-100 point gain when guided by an error log."},{"q":"It's the last two days before your test date. Best move?","choices":["Cram a new prep book cover to cover","Take three more full tests back to back","Taper: light flashcards, checklist, sleep","Study 8 hours both days to be safe"],"answer":2,"explain":"New material doesn't stick in 48 hours and fatigue creates careless errors. Tapering — light review, logistics, sleep — delivers the work you already did."}]},{"id":"skills-pomodoro-technique","title":"Study Skills: Pomodoro Technique","topic":"Study Skills","questions":[{"q":"The classic Pomodoro cycle is:","choices":["2 hours work, 30 minutes break","25 minutes work, 5 minutes break","10 minutes work, 20 minutes break","work until tired, then nap"],"answer":1,"explain":"25 minutes on, 5 off — and after four cycles, a longer 15-30 minute break. The short sprint is what makes starting easy and focus sustainable."},{"q":"During your 5-minute break, the best activity is:","choices":["scrolling social media","starting a new episode","standing, stretching or getting water","planning next week"],"answer":2,"explain":"Movement plus low-information rest actually restores attention. Feeds flood your brain with new content, so the next sprint starts noisy — that's the classic fake break."},{"q":"Mid-sprint you remember you need to reply to a friend. Correct move?","choices":["Reply now, quickly","Write it on your distraction pad and keep working","End the sprint entirely","Switch to messaging for the rest of the sprint"],"answer":1,"explain":"The distraction pad parks the thought without acting on it. Acting — even 'quickly' — pays the switch cost and invites the next interruption. Handle it on the break."},{"q":"You're doing deep math problem sets and 25 minutes keeps cutting your thinking short. Best adaptation?","choices":["Abandon timers entirely","Take a break every time you feel like it","Use 45-50 minute sprints with 10-minute breaks","Do two sprints back to back with no break"],"answer":2,"explain":"The 25/5 default bends to the work: deep tasks fit longer sprints. What stays fixed is the single-task rule and real breaks — skipping breaks to 'bank time' just drains you."}]},{"id":"skills-active-recall","title":"Study Skills: Active Recall","topic":"Study Skills","questions":[{"q":"Which activity counts as active recall?","choices":["Highlighting the textbook chapter","Re-reading notes three times","Closing the book and writing what you remember","Watching a review video at 2x speed"],"answer":2,"explain":"Only the third one pulls information OUT of memory — that retrieval is the learning event. The others re-expose you to material, which builds familiarity, not recall."},{"q":"The 'fluency illusion' means:","choices":["speaking multiple languages helps studying","familiarity with a page is mistaken for knowing it","fast readers learn faster","notes should be rewritten neatly"],"answer":1,"explain":"Re-reading makes material feel fluent and familiar, and the brain misreads that feeling as knowledge — until the blank exam page exposes the difference."},{"q":"You flip a flashcard after 2 seconds because you 'sort of know it.' This is:","choices":["fine if you were close","turning recall into recognition — a key failure mode","the recommended technique","only bad for vocabulary"],"answer":1,"explain":"The retrieval attempt — even a slow, effortful, failed one — is the rep that strengthens memory. Two-second flips convert practice back into passive recognizing."},{"q":"You try to recall a definition and completely blank. Research suggests the best next step is:","choices":["skip it — the method failed","read the answer, then retest yourself shortly after","move to a different subject entirely","highlight the definition"],"answer":1,"explain":"A failed retrieval followed by the correct answer produces better memory than never attempting — the failed search primes the memory to stick. Retest within the session."}]},{"id":"skills-spaced-repetition","title":"Study Skills: Spaced Repetition","topic":"Study Skills","questions":[{"q":"The forgetting curve shows that, without review, most new material is forgotten within:","choices":["a year","24-48 hours","one class period","never — memory is permanent"],"answer":1,"explain":"Ebbinghaus found the curve is steepest early: the majority of new learning fades within a day or two untouched. Spaced reviews flatten that cliff."},{"q":"According to spaced repetition, the best time to review material is:","choices":["immediately after learning it","right when you're about to forget it","only during finals week","whenever you feel like it"],"answer":1,"explain":"A review that lands just before forgetting makes retrieval effortful (strengthening the memory) while still mostly successful — that timing flattens the curve most per minute spent."},{"q":"Which is a reasonable beginner interval ladder?","choices":["every hour on the hour, forever","once, three months later","1 day → 3 days → 1 week → 2 weeks → monthly","only the night before each test"],"answer":2,"explain":"Expanding intervals match how memory consolidates: each successful spaced review roughly doubles the memory's survival time, so the gaps grow."},{"q":"You miss a flashcard that was scheduled for a 2-week interval. Spaced repetition says:","choices":["skip it — you'll get it eventually","reset it to a short interval like tomorrow","move it to an even longer interval","delete the card"],"answer":1,"explain":"A failed retrieval means the memory hasn't consolidated at that gap — bring it back soon (tomorrow), rebuild it, then re-expand. Failure resets the ladder."}]},{"id":"skills-note-taking-methods","title":"Study Skills: Note-Taking Methods","topic":"Study Skills","questions":[{"q":"In the Cornell method, the left-hand cue column is filled:","choices":["within 24 hours after class, with questions and keywords","during class, verbatim","only before the final exam","by the teacher afterward"],"answer":0,"explain":"Notes go on the right during class; the cue column is written after, converting your notes into a cover-and-recall quiz — that after-class pass is also a perfectly timed spaced review."},{"q":"Your history teacher lectures war-by-war with the same categories each time. Best method?","choices":["Mind map","Charting with columns","Verbatim transcript","No notes — just listen"],"answer":1,"explain":"When topics repeat the same categories, columns (war / cause / key figure / outcome) make each new item instantly comparable — charting exists for exactly this pattern."},{"q":"The 24-hour rule says you should:","choices":["wait a day before taking any notes","study each subject only once daily","revisit and complete each page of notes within a day of class","keep notes for 24 hours then recycle them"],"answer":2,"explain":"One revisit within a day catches the steepest part of the forgetting curve — filling gaps and adding cues takes five minutes and roughly doubles what survives to test week."},{"q":"Research suggests handwriting often beats typing for learning because:","choices":["pens are more accurate than keyboards","slowness forces summarizing, and the summarizing is the processing","teachers grade handwriting","screens emit harmful light"],"answer":1,"explain":"Handwriting can't keep pace with verbatim transcription, so you must compress ideas into your own words — and that compression, not the ink, is what builds understanding."}]},{"id":"skills-exam-anxiety","title":"Study Skills: Exam Anxiety","topic":"Study Skills","questions":[{"q":"You blank on material you studied last night. Most likely cause?","choices":["you never knew it","anxiety hijacked your working memory","the material was wrong","you studied too thoroughly"],"answer":1,"explain":"The fight-or-flight response borrows working memory for survival processing. The knowledge usually exists — it's temporarily inaccessible — which is why calming tools restore access faster than trying to force the memory."},{"q":"Which breathing pattern most directly calms the nervous system?","choices":["Quick shallow breaths","Hold your breath as long as possible","Exhale longer than you inhale","No pattern — just breathe faster"],"answer":2,"explain":"Extended exhales (as in box breathing or the physiological sigh) activate the parasympathetic brake and lower heart rate within about a minute."},{"q":"The Yerkes-Dodson principle says peak performance comes:","choices":["when completely relaxed","at moderate arousal — some nerves help","only under extreme pressure","when you feel nothing at all"],"answer":1,"explain":"Both extremes hurt: zero arousal is sluggish, extreme arousal is chaotic. The goal is managing nerves below the ceiling — not eliminating them, which isn't necessary or even helpful."},{"q":"Five minutes before the exam, waiting outside the room, your best move is:","choices":["frantically re-read your notes","compare answers with classmates","slow exhales plus grounding, then walk in","convince yourself the test doesn't matter"],"answer":2,"explain":"Last-minute cramming adds noise and feeds doubt; the material is what it is. Calming your system protects your ability to access what you already know — that's where the points are."}]},{"id":"skills-memory-techniques","title":"Study Skills: Memory Techniques","topic":"Study Skills","questions":[{"q":"HOMES for the Great Lakes is an example of:","choices":["an acrostic","a memory palace","an acronym","chunking"],"answer":2,"explain":"HOMES is an acronym: the first letters of the list form a single word, which serves as one retrieval cue that unpacks into five lakes. An acrostic would be a sentence instead."},{"q":"A memory palace works primarily because:","choices":["palaces are interesting","spatial memory is extremely strong and reliable","it shortens the list","kings had good memories"],"answer":1,"explain":"Your brain never forgets layouts of familiar places — binding new facts to that rock-solid spatial system gives abstract information the same durability."},{"q":"Remembering 149217761945 as '1492-1776-1945' is:","choices":["an acronym","chunking","the method of loci","re-reading"],"answer":1,"explain":"Grouping digits into meaningful units (famous years) turns 12 memory items into 3 chunks — chunking multiplies working memory capacity without changing its slot count."},{"q":"You need to memorize the planets in order tonight. Best approach?","choices":["read the list 20 times","create your own weird acrostic sentence, then test yourself in an hour","copy the list neatly","just hope it comes back during the test"],"answer":1,"explain":"A self-made, strange acrostic gives you one cue that unpacks in order, and creating it is itself elaborative encoding. Re-test after an hour and again tomorrow to make it permanent."}]}],"pillars":[{"slug":"math","title":"Math","emoji":"➗","clusters":[{"slug":"algebra-basics","title":"Algebra Basics"},{"slug":"fractions-decimals-percents","title":"Fractions, Decimals & Percents"},{"slug":"geometry-fundamentals","title":"Geometry Fundamentals"},{"slug":"trigonometry-essentials","title":"Trigonometry Essentials"},{"slug":"linear-equations-graphing","title":"Linear Equations & Graphing"},{"slug":"word-problems-strategies","title":"Word Problem Strategies"}]},{"slug":"biology","title":"Biology","emoji":"🧬","clusters":[{"slug":"cell-basics","title":"Cell Basics"},{"slug":"photosynthesis","title":"Photosynthesis"},{"slug":"dna-and-genetics","title":"DNA & Genetics"},{"slug":"human-body-systems","title":"Human Body Systems"},{"slug":"ecosystems","title":"Ecosystems"},{"slug":"mitosis-vs-meiosis","title":"Mitosis vs Meiosis"}]},{"slug":"chemistry","title":"Chemistry","emoji":"⚗️","clusters":[{"slug":"atomic-structure","title":"Atomic Structure"},{"slug":"periodic-table","title":"Periodic Table"},{"slug":"chemical-bonding","title":"Chemical Bonding"},{"slug":"chemical-reactions","title":"Chemical Reactions"},{"slug":"moles-and-stoichiometry","title":"Moles & Stoichiometry"},{"slug":"acids-and-bases","title":"Acids & Bases"}]},{"slug":"physics","title":"Physics","emoji":"⚛️","clusters":[{"slug":"motion-and-forces","title":"Motion and Forces"},{"slug":"energy-work-power","title":"Energy, Work and Power"},{"slug":"waves-and-sound","title":"Waves and Sound"},{"slug":"electricity-basics","title":"Electricity Basics"},{"slug":"magnetism","title":"Magnetism"},{"slug":"light-and-optics","title":"Light and Optics"}]},{"slug":"history","title":"History","emoji":"🏛️","clusters":[{"slug":"ancient-civilizations","title":"Ancient Civilizations"},{"slug":"american-revolution","title":"American Revolution"},{"slug":"world-war-i","title":"World War I"},{"slug":"world-war-ii","title":"World War II"},{"slug":"cold-war","title":"Cold War"},{"slug":"civil-rights-movement","title":"Civil Rights Movement"}]},{"slug":"sat","title":"SAT Prep","emoji":"🎓","clusters":[{"slug":"sat-reading-strategies","title":"SAT Reading Strategies"},{"slug":"sat-writing-grammar","title":"SAT Writing & Grammar"},{"slug":"sat-math-strategies","title":"SAT Math Strategies"},{"slug":"sat-vocabulary","title":"SAT Vocabulary"},{"slug":"sat-test-day-tips","title":"SAT Test Day Tips"},{"slug":"sat-study-schedule","title":"SAT Study Schedule"}]},{"slug":"skills","title":"Study Skills","emoji":"🧠","clusters":[{"slug":"pomodoro-technique","title":"Pomodoro Technique"},{"slug":"active-recall","title":"Active Recall"},{"slug":"spaced-repetition","title":"Spaced Repetition"},{"slug":"note-taking-methods","title":"Note-Taking Methods"},{"slug":"exam-anxiety","title":"Exam Anxiety"},{"slug":"memory-techniques","title":"Memory Techniques"}]}]};
